// Purpose: ROW-031 (INV-001; REQ-011..REQ-015) — on the checker page, in every browser of the harness,
// over generated sequences of checks, replacements and ignores on generated offers, the text Copy text
// returns differs from the pasted text only at the replaced words; every sequence holds a
// length-changing Replace placed before another flagged word on the same line, then a second Replace
// on that word, then Copy text.
// Provenance: generated by tests/invariants/suggestions-population.ts from dictionary-es 4.0.0 (the
// SHA-256-pinned oracle, D-029) with a fresh seed per run (the sequence too); the expected text is the
// test's own model — the pasted text with each chosen suggestion at the place the test tracks.
//
// Test argument
// ROW-031 promise: over generated sequences of checks, replacements and ignores on generated offers,
//   the text Copy text returns differs from the pasted text only at the replaced words (INV-001,
//   "whatever sequence of checks, replacements and ignores came between"; A-018, A-019).
// ROW-031 wrong product: a page that keeps the offsets of the last check and applies a second Replace
//   at them — after "verzsado" became "versado" (one shorter), the next Replace on the same line lands
//   one character early and eats a letter of its neighbour; or one that rebuilds the text from words
//   and loses the tab or the blank line.
// ROW-031 given: two generated offers per run (three lines with a bullet, a tab and a blank line,
//   five generated misspellings with a known correction: A an insertion error and B later on A's
//   line, the rest elsewhere), each pasted with the browser's paste; when: a generated sequence —
//   check; Replace A by a suggestion of another length; 0–2 random steps (Ignore a flagged word, or
//   check again); Replace B; 0–2 random steps; Copy text; then: after every step the box holds the
//   model text, and the clipboard holds exactly the model text: the pasted text with only A and B
//   replaced by the suggestions chosen.
// ROW-031 controls: the same offer, pasted and checked, is highlighted at every modelled place — the
//   model and the page agree before any Replace; untouched by an offset fault.
// ROW-031 technique: a property over generated offers and generated sequences, with the row's named
//   harmful shape forced into every sequence; the seed recorded for replay.
// cases: ROW-031 target=ROW-031-copy-text-returns-the-pasted-text-changed-only-at-the-replaced-words control=ROW-031-control-the-pasted-offer-is-highlighted-at-every-modelled-place

import { expect, test, type BrowserContext, type Page } from '@playwright/test';
import { asActor, freshRandom, openChecker, pressCheck, readHighlights, el, ROLES, type Rng } from './harness';
import {
  chooseIgnore,
  chooseSuggestion,
  openMenuByPointer,
  pasteIntoOffer,
  press,
  putOnClipboard,
  readClipboard,
  readMenu,
  readMessage,
  readOfferText,
  scratchPage,
} from './suggestions-helpers';
import { uniqueCorrectionErrors, type Misspelling } from './suggestions-population';

const WAIT_MS = 15_000;

type Tracked = { m: Misspelling; start: number; word: string; replaced: boolean; ignored: boolean };

function generatedOffer(rng: Rng) {
  const [a] = uniqueCorrectionErrors(rng, 1, ['insertion']);
  let rest = uniqueCorrectionErrors(rng, 4).filter((m) => m.intended !== a.intended && m.wrong !== a.wrong);
  while (rest.length < 4) rest = rest.concat(uniqueCorrectionErrors(rng, 1).filter((m) => m.intended !== a.intended && !rest.some((r) => r.wrong === m.wrong)));
  const [b, c, d, e] = rest;
  const lines = [
    `Buscamos ${a.wrong} para el ${b.wrong} del equipo`,
    '',
    `•\tTareas: ${c.wrong} con  clientes y ${d.wrong}`,
    `Ofrecemos contrato y ${e.wrong}.`,
  ];
  const text = lines.join('\n');
  const tracked: Tracked[] = [];
  let from = 0;
  for (const m of [a, b, c, d, e]) {
    const start = text.indexOf(m.wrong, from);
    tracked.push({ m, start, word: m.wrong, replaced: false, ignored: false });
    from = start + m.wrong.length;
  }
  return { text, tracked };
}

const highlightedNow = (t: Tracked[]) => t.filter((x) => !x.replaced && !x.ignored).sort((p, q) => p.start - q.start).map((x) => `${x.word}@${x.start}`);

async function pasted(page: Page, context: BrowserContext, text: string) {
  const scratch = await scratchPage(context);
  await putOnClipboard(scratch, text);
  await openChecker(page);
  await pasteIntoOffer(page);
  await expect.poll(() => readOfferText(page), { message: 'ROW-031: the paste put the offer in the box', timeout: WAIT_MS }).toBe(text);
  return scratch;
}

async function check(page: Page, model: string, t: Tracked[], log: string[]) {
  log.push('check');
  for (const x of t) x.ignored = false;
  expect((await pressCheck(page)).status, `ROW-031: the check is answered — ${log.join(' → ')}`).toBe(200);
  const want = highlightedNow(t);
  await expect
    .poll(async () => {
      const got = (await readHighlights(page, model)).map((h) => `${h.word}@${h.start}`);
      return want.filter((w) => got.includes(w));
    }, { message: `ROW-031: every unreplaced misspelling is highlighted at its modelled place — ${log.join(' → ')}`, timeout: WAIT_MS })
    .toEqual(want);
}

async function replace(page: Page, model: string, t: Tracked[], x: Tracked, log: string[], mustChangeLength: boolean): Promise<string> {
  await openMenuByPointer(page, model, x.start, 'ROW-031');
  const menu = await readMenu(page);
  const label = menu.suggestions.find((s) => s === x.m.intended && (!mustChangeLength || s.length !== x.word.length)) ?? menu.suggestions.find((s) => !mustChangeLength || s.length !== x.word.length);
  expect(label, `ROW-031: "${x.word}"'s menu offers a suggestion${mustChangeLength ? ' of another length' : ''} — ${JSON.stringify(menu)} — ${log.join(' → ')}`).toBeTruthy();
  log.push(`replace ${x.word}@${x.start}→${label}`);
  await chooseSuggestion(page, label!, 'ROW-031');
  const next = model.slice(0, x.start) + label + model.slice(x.start + x.word.length);
  const shift = label!.length - x.word.length;
  for (const y of t) if (y !== x && y.start > x.start) y.start += shift;
  x.replaced = true;
  await expect.poll(() => readOfferText(page), { message: `ROW-031: after the Replace the box holds the model text — ${log.join(' → ')}`, timeout: WAIT_MS }).toBe(next);
  return next;
}

async function ignore(page: Page, model: string, x: Tracked, log: string[]) {
  log.push(`ignore ${x.word}@${x.start}`);
  await openMenuByPointer(page, model, x.start, 'ROW-031');
  await chooseIgnore(page, 'ROW-031');
  x.ignored = true;
  await expect.poll(() => readOfferText(page), { message: `ROW-031: Ignore leaves the model text — ${log.join(' → ')}`, timeout: WAIT_MS }).toBe(model);
}

async function randomSteps(page: Page, rng: Rng, model: string, t: Tracked[], keep: Tracked | null, log: string[]) {
  for (let i = rng.int(3); i > 0; i--) {
    const open = t.filter((x) => !x.replaced && !x.ignored && x !== keep);
    if (open.length && rng.int(2) === 0) await ignore(page, model, rng.pick(open), log);
    else await check(page, model, t, log);
  }
}

test('ROW-031-copy-text-returns-the-pasted-text-changed-only-at-the-replaced-words', async ({ page, context }) => {
  asActor('anonymous');
  const rng = freshRandom();
  for (let run = 1; run <= 2; run++) {
    const { text, tracked } = generatedOffer(rng);
    const log: string[] = [`sequence ${run} (seed ${rng.seed})`];
    const scratch = await pasted(page, context, text);
    let model = text;
    const [a, b] = tracked;

    await check(page, model, tracked, log);
    model = await replace(page, model, tracked, a, log, true);
    await randomSteps(page, rng, model, tracked, b, log);
    if (b.ignored) await check(page, model, tracked, log);
    model = await replace(page, model, tracked, b, log, false);
    await randomSteps(page, rng, model, tracked, null, log);

    log.push('copy');
    await page.bringToFront();
    await press(page, el(page, ROLES.copy).first());
    await expect.poll(() => readMessage(page), { message: `ROW-031: Copy text confirms — ${log.join(' → ')}`, timeout: WAIT_MS }).toMatch(/copiad[oa]/i);
    expect((await readClipboard(scratch)).text, `ROW-031: Copy text returns the pasted text changed only at the replaced words — ${log.join(' → ')}`).toBe(model);
    await scratch.close();
  }
});

test('ROW-031-control-the-pasted-offer-is-highlighted-at-every-modelled-place', async ({ page, context }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const { text, tracked } = generatedOffer(rng);
  await pasted(page, context, text);
  expect((await pressCheck(page)).status, 'ROW-031 control: the check is answered').toBe(200);
  await expect
    .poll(async () => (await readHighlights(page, text)).map((h) => `${h.word}@${h.start}`), { message: `ROW-031 control: the offer's misspellings are highlighted at their modelled places (seed ${rng.seed})`, timeout: WAIT_MS })
    .toEqual(highlightedNow(tracked));
});
